using UnityEngine;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

public class TcpClientExample : MonoBehaviour
{
    private TcpClient client;
    private const string serverIp = "127.0.0.1"; // Replace with your server IP
    private const int serverPort = 12345; // Replace with your server port

    async void Start()
    {
        client = new TcpClient();
        await ConnectToServer();
        await SendMessage("Hello, Server!");
        await ReceiveMessage();
    }

    private async Task ConnectToServer()
    {
        await client.ConnectAsync(serverIp, serverPort);
        Debug.Log("Connected to server.");
    }

    private async Task SendMessage(string message)
    {
        byte[] data = Encoding.ASCII.GetBytes(message);
        await client.GetStream().WriteAsync(data, 0, data.Length);
        Debug.Log("Message sent: " + message);
    }

    private async Task ReceiveMessage()
    {
        byte[] buffer = new byte[1024];
        int bytesRead = await client.GetStream().ReadAsync(buffer, 0, buffer.Length);
        string response = Encoding.ASCII.GetString(buffer, 0, bytesRead);
        Debug.Log("Received: " + response);
    }

    private void OnApplicationQuit()
    {
        client?.Close();
    }
}
```

