        {
            linesQueue.Enqueue(line);
        }
    }

    public void Shutdown()
    {
        lock(locker)
        {
            isShutdown = true;
        }
    }
}

class Program
{
    static void Main()
    {
        List<Worker> workers = new List<Worker>();
        for (int i = 0; i < 32; i++)
        {
