```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    // Create a bounded BlockingCollection to hold the lines to be processed
    private static BlockingCollection<string> lineCollection = new BlockingCollection<string>(boundedCapacity: 100);
    private static CancellationTokenSource cancellationTokenSource = new CancellationTokenSource();
    private static int numberOfWorkers = 32;

    static void Main(string[] args)
    {
        // Start worker threads
        for (int i = 0; i < numberOfWorkers; i++)
        {
            Task.Factory.StartNew(WorkerThread, cancellationTokenSource.Token);
        }

        // Read lines from the file and add them to the collection
        using (var reader = new StreamReader("path_to_your_textfile.txt"))
        {
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                lineCollection.Add(line); // This will block if the collection is full
            }
        }

        // Indicate that there are no more items to be added
        lineCollection.CompleteAdding();

        // Wait for all worker threads to finish
        cancellationTokenSource.CancelAfter(30000); // Optional timeout for graceful shutdown
        Task.WaitAll();

        Console.WriteLine("All workers have completed processing.");
    }

    private static void WorkerThread(object obj)
    {
        try
        {
            foreach (var line in lineCollection.GetConsumingEnumerable(cancellationTokenSource.Token))
            {
                // Simulate processing the line
                ProcessLine(line);
            }
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine("Worker thread is shutting down.");
        }
    }

    private static void ProcessLine(string line)
    {
        // Simulate some work with the line
        Console.WriteLine($"Processing: {line}");
        Thread.Sleep(100); // Simulated processing time
    }
}
```

### Explanation:

1. **BlockingCollection**: We use `BlockingCollection<string>` to manage the lines. It’s thread-safe and provides a way to block the thread that attempts to add lines when the collection reaches its capacity. 

2. **Worker Threads**: The main thread spawns 32 worker tasks, each running the `WorkerThread` method which processes lines from the `BlockingCollection`.

3. **File Reading**: The text file is read line-by-line within a `using` block to ensure proper disposal of resources. When a line is read, it is added to the `BlockingCollection`.

4. **Completion Notification**: After all lines are added, `CompleteAdding` is called to notify all worker threads that there will be no more items added, allowing them to terminate gracefully once they finish processing.

5. **Graceful Shutdown**: The `CancellationTokenSource` is used to allow for a graceful shutdown of the worker tasks and to catch any potential `OperationCanceledExceptions` if the token is canceled.

6. **Task.WaitAll()**: This method is invoked to block the main thread until all workers are finished processing.

This approach ensures that you maintain efficient resource usage by controlling the concurrency level and waiting for each worker to complete their task before shutting down, thereby embodying good multithreading practices in C#.

