```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>

int main() {
    // Prompt for the filename and the word to search
    std::string filename, targetWord;
    std::cout << "Enter the filename: ";
    std::getline(std::cin, filename);
    std::cout << "Enter the word to count: ";
    std::getline(std::cin, targetWord);

    std::ifstream inputFile(filename); // Create an input file stream
    if (!inputFile) {
        std::cerr << "Could not open the file: " << filename << std::endl;
        return 1; // Exit the program if the file cannot be opened
    }

    std::string line;
    int wordCount = 0; // Initialize the word count

    // Read the file line by line
    while (std::getline(inputFile, line)) {
        std::istringstream lineStream(line); // Stream for extracting words from the line
        std::string word;

        // Extract each word from the line
        while (lineStream >> word) {
            // Compare the current word with the target word
            if (word == targetWord) {
                ++wordCount; // Increment count if there's a match
            }
        }
    }

    inputFile.close(); // Close the file stream

